def load_cilm(path, lmax):
    c = np.zeros((2, lmax + 1, lmax + 1))
    with open(path) as fh:
        for line in fh:
            p = line.split()
            if len(p) < 4:
                continue
            l, m = int(p[0]), int(p[1])
            if l <= lmax:
                c[0, l, m] = float(p[2])
                c[1, l, m] = float(p[3])
    return c

